1	/**
2	 * A faithful subset of CPython 3.12's `argparse`.
3	 *
4	 * Only what this program's parser can reach is modelled — optionals with
5	 * `nargs=None` plus the automatic `-h/--help` — but within that subset the
6	 * observable behaviour is reproduced precisely: prefix abbreviation, `--opt=value`,
7	 * the `--` terminator, the negative-number heuristic, the space heuristic,
8	 * short-option tails such as `-hx`, ambiguity reporting, the ordering of the
9	 * "required" check before the "unrecognized" check, and exit statuses.
10	 */
11	
12	import { HelpFormatter } from './argparseFormatter.mjs';
13	import { exit, terminalColumns, writeStderr, writeStdout } from './sys.mjs';
14	
15	const PREFIX_CHARS = '-';
16	
17	/** argparse's `_negative_number_matcher`. */
18	const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
19	
20	/** Exit status argparse uses for command-line errors. */
21	const USAGE_ERROR_STATUS = 2;
22	
23	/**
24	 * One command-line action.
25	 */
26	class Action {
27	  /**
28	   * @param {string[]} optionStrings e.g. ['-h', '--help']
29	   * @param {{kind?: 'store' | 'help', dest?: string, metavar?: string,
30	   *          required?: boolean, help?: string}} options
31	   */
32	  constructor(optionStrings, options = {}) {
33	    this.optionStrings = optionStrings;
34	    this.kind = options.kind ?? 'store';
35	    this.required = options.required ?? false;
36	    this.help = options.help ?? '';
37	    this.nargs = this.kind === 'help' ? 0 : null;
38	    this.dest = options.dest ?? Action.defaultDest(optionStrings);
39	    this.metavar = options.metavar ?? this.dest.toUpperCase();
40	  }
41	
42	  /**
43	   * argparse derives `dest` from the first long option string.
44	   *
45	   * @param {string[]} optionStrings
46	   * @returns {string}
47	   */
48	  static defaultDest(optionStrings) {
49	    const long = optionStrings.find((option) => option.startsWith('--')) ?? optionStrings[0];
50	    return long.replace(/^-+/, '').replace(/-/g, '_');
51	  }
52	
53	  /** `_get_action_name`: how the action is named in error messages. */
54	  get displayName() {
55	    return this.optionStrings.join('/');
56	  }
57	}
58	
59	export class ArgumentParser {
60	  /**
61	   * @param {{prog: string}} options
62	   */
63	  constructor({ prog }) {
64	    this.prog = prog;
65	    /** @type {Action[]} */
66	    this.actions = [];
67	    /** @type {Map<string, Action>} */
68	    this.optionStringActions = new Map();
69	    this.addArgument(['-h', '--help'], {
70	      kind: 'help',
71	      help: 'show this help message and exit',
72	    });
73	  }
74	
75	  /**
76	   * Register an option.
77	   *
78	   * @param {string[]} optionStrings
79	   * @param {object} [options] see {@link Action}
80	   * @returns {Action}
81	   */
82	  addArgument(optionStrings, options = {}) {
83	    const action = new Action(optionStrings, options);
84	    this.actions.push(action);
85	    for (const optionString of optionStrings) {
86	      this.optionStringActions.set(optionString, action);
87	    }
88	    return action;
89	  }
90	
91	  /** @returns {HelpFormatter} */
92	  formatter() {
93	    return new HelpFormatter(this.prog, terminalColumns());
94	  }
95	
96	  /** @returns {string} */
97	  formatUsage() {
98	    return this.formatter().formatUsage(this.actions);
99	  }
100	
101	  /** @returns {string} */
102	  formatHelp() {
103	    return this.formatter().formatHelp(this.actions);
104	  }
105	
106	  /**
107	   * `parser.error`: usage plus a diagnostic on stderr, then exit status 2.
108	   *
109	   * @param {string} message
110	   * @returns {never}
111	   */
112	  error(message) {
113	    writeStderr(this.formatUsage());
114	    writeStderr(`${this.prog}: error: ${message}\n`);
115	    return exit(USAGE_ERROR_STATUS);
116	  }
117	
118	  /**
119	   * Classify one token: `null` means "positional", otherwise a tuple of the
120	   * matched action (or `null` for an unknown option), the option string, and
121	   * any value glued on with `=`.
122	   *
123	   * @param {string} token
124	   * @returns {{action: Action | null, optionString: string, explicitArg: string | null} | null}
125	   */
126	  parseOptional(token) {
127	    if (token === '') return null;
128	    if (!PREFIX_CHARS.includes(token[0])) return null;
129	
130	    const exact = this.optionStringActions.get(token);
131	    if (exact !== undefined) return { action: exact, optionString: token, explicitArg: null };
132	
133	    if (token.length === 1) return null; // a bare '-' is a positional
134	
135	    const equals = token.indexOf('=');
136	    if (equals !== -1) {
137	      const head = token.slice(0, equals);
138	      const action = this.optionStringActions.get(head);
139	      if (action !== undefined) {
140	        return { action, optionString: head, explicitArg: token.slice(equals + 1) };
141	      }
142	    }
143	
144	    const candidates = this.getOptionTuples(token);
145	    if (candidates.length > 1) {
146	      const matches = candidates.map((candidate) => candidate.optionString).join(', ');
147	      this.error(`ambiguous option: ${token} could match ${matches}`);
148	    }
149	    if (candidates.length === 1) return candidates[0];
150	
151	    if (NEGATIVE_NUMBER.test(token)) return null; // meant to be a negative number
152	    if (token.includes(' ')) return null; // meant to be a positional
153	
154	    return { action: null, optionString: token, explicitArg: null };
155	  }
156	
157	  /**
158	   * All options an abbreviation could refer to (`_get_option_tuples`).
159	   *
160	   * @param {string} token
161	   * @returns {{action: Action, optionString: string, explicitArg: string | null}[]}
162	   */
163	  getOptionTuples(token) {
164	    const result = [];
165	    const doubleDash = PREFIX_CHARS.includes(token[0]) && PREFIX_CHARS.includes(token[1]);
166	
167	    if (doubleDash) {
168	      const equals = token.indexOf('=');
169	      const optionPrefix = equals === -1 ? token : token.slice(0, equals);
170	      const explicitArg = equals === -1 ? null : token.slice(equals + 1);
171	      for (const [optionString, action] of this.optionStringActions) {
172	        if (optionString.startsWith(optionPrefix)) {
173	          result.push({ action, optionString, explicitArg });
174	        }
175	      }
176	      return result;
177	    }
178	
179	    // Single dash: either an exact short option with its value glued on, or an
180	    // abbreviation of a longer single-dash option.
181	    const shortOptionPrefix = token.slice(0, 2);
182	    const shortExplicitArg = token.slice(2);
183	    for (const [optionString, action] of this.optionStringActions) {
184	      if (optionString === shortOptionPrefix) {
185	        result.push({ action, optionString, explicitArg: shortExplicitArg });
186	      } else if (optionString.startsWith(token)) {
187	        result.push({ action, optionString, explicitArg: null });
188	      }
189	    }
190	    return result;
191	  }
192	
193	  /**
194	   * `_match_argument` for the nargs values this parser uses. Optionals never
195	   * consume `--`, so the pattern for `nargs=None` is simply a single 'A'.
196	   *
197	   * @param {Action} action
198	   * @param {string} patterns remaining token-class pattern
199	   * @returns {number} how many tokens the action consumes
200	   */
201	  matchArgument(action, patterns) {
202	    if (action.nargs === 0) return 0;
203	    if (patterns.startsWith('A')) return 1;
204	    return this.error(`argument ${action.displayName}: expected one argument`);
205	  }
206	
207	  /**
208	   * Parse, tolerating unknown tokens by collecting them.
209	   *
210	   * @param {string[]} argv
211	   * @returns {[Record<string, string | null>, string[]]}
212	   */
213	  parseKnownArgs(argv) {
214	    /** @type {Record<string, string | null>} */
215	    const namespace = {};
216	    for (const action of this.actions) {
217	      if (action.kind === 'store') namespace[action.dest] = null;
218	    }
219	
220	    // Classify every token up front; the first '--' makes all that follow
221	    // positional, and is itself neither option nor value.
222	    const patterns = [];
223	    /** @type {Map<number, {action: Action | null, optionString: string, explicitArg: string | null}>} */
224	    const optionTuples = new Map();
225	    let terminated = false;
226	    for (let i = 0; i < argv.length; i += 1) {
227	      if (!terminated && argv[i] === '--') {
228	        patterns.push('-');
229	        terminated = true;
230	        continue;
231	      }
232	      if (terminated) {
233	        patterns.push('A');
234	        continue;
235	      }
236	      const tuple = this.parseOptional(argv[i]);
237	      if (tuple === null) {
238	        patterns.push('A');
239	      } else {
240	        optionTuples.set(i, tuple);
241	        patterns.push('O');
242	      }
243	    }
244	    const patternString = patterns.join('');
245	
246	    /** @type {string[]} */
247	    const extras = [];
248	    /** @type {Set<Action>} */
249	    const seen = new Set();
250	
251	    /**
252	     * Apply an action, which for `--help` never returns.
253	     *
254	     * @param {Action} action
255	     * @param {string[]} values
256	     */
257	    const takeAction = (action, values) => {
258	      seen.add(action);
259	      if (action.kind === 'help') {
260	        writeStdout(this.formatHelp());
261	        exit(0);
262	      }
263	      namespace[action.dest] = values[0];
264	    };
265	
266	    let index = 0;
267	    while (index < argv.length) {
268	      if (patternString[index] !== 'O') {
269	        // No positionals are defined, so every positional token is a leftover.
270	        extras.push(argv[index]);
271	        index += 1;
272	        continue;
273	      }
274	      index = this.consumeOptional(index, argv, patternString, optionTuples, extras, takeAction);
275	    }
276	
277	    const missing = this.actions
278	      .filter((action) => action.required && !seen.has(action))
279	      .map((action) => action.displayName);
280	    if (missing.length > 0) {
281	      this.error(`the following arguments are required: ${missing.join(', ')}`);
282	    }
283	
284	    return [namespace, extras];
285	  }
286	
287	  /**
288	   * Consume one option and its value, returning the next index to look at.
289	   *
290	   * @param {number} startIndex
291	   * @param {string[]} argv
292	   * @param {string} patternString
293	   * @param {Map<number, object>} optionTuples
294	   * @param {string[]} extras
295	   * @param {(action: Action, values: string[]) => void} takeAction
296	   * @returns {number}
297	   */
298	  consumeOptional(startIndex, argv, patternString, optionTuples, extras, takeAction) {
299	    let { action, optionString, explicitArg } = optionTuples.get(startIndex);
300	    /** @type {[Action, string[]][]} */
301	    const pending = [];
302	    let stop = startIndex + 1;
303	
304	    for (;;) {
305	      if (action === null) {
306	        // An option nobody declared: hand the token back as a leftover.
307	        extras.push(argv[startIndex]);
308	        return startIndex + 1;
309	      }
310	
311	      if (explicitArg !== null) {
312	        const argCount = this.matchArgument(action, 'A');
313	        if (argCount === 0 && !PREFIX_CHARS.includes(optionString[1]) && explicitArg !== '') {
314	          // A short flag with a tail, e.g. '-hx': run the flag, then try to
315	          // read the tail as another short option.
316	          pending.push([action, []]);
317	          const prefixChar = optionString[0];
318	          optionString = prefixChar + explicitArg[0];
319	          const remainder = explicitArg.slice(1) === '' ? null : explicitArg.slice(1);
320	          const next = this.optionStringActions.get(optionString);
321	          if (next !== undefined) {
322	            action = next;
323	            explicitArg = remainder;
324	            continue;
325	          }
326	          extras.push(prefixChar + explicitArg);
327	          stop = startIndex + 1;
328	          break;
329	        }
330	        if (argCount === 1) {
331	          pending.push([action, [explicitArg]]);
332	          stop = startIndex + 1;
333	          break;
334	        }
335	        this.error(`argument ${action.displayName}: ignored explicit argument '${explicitArg}'`);
336	      }
337	
338	      const valueStart = startIndex + 1;
339	      const argCount = this.matchArgument(action, patternString.slice(valueStart));
340	      stop = valueStart + argCount;
341	      pending.push([action, argv.slice(valueStart, stop)]);
342	      break;
343	    }
344	
345	    for (const [pendingAction, values] of pending) takeAction(pendingAction, values);
346	    return stop;
347	  }
348	
349	  /**
350	   * Parse, rejecting anything left over.
351	   *
352	   * @param {string[]} argv
353	   * @returns {Record<string, string | null>}
354	   */
355	  parseArgs(argv) {
356	    const [namespace, extras] = this.parseKnownArgs(argv);
357	    if (extras.length > 0) {
358	      this.error(`unrecognized arguments: ${extras.join(' ')}`);
359	    }
360	    return namespace;
361	  }
362	}
