1	/**
2	 * argparse's `HelpFormatter`, reduced to the cases this parser can produce
3	 * (optionals only, at most one metavar each) but keeping the real layout
4	 * arithmetic: help-column placement, usage wrapping and help-text wrapping all
5	 * respond to the terminal width exactly as CPython 3.12 does.
6	 */
7	
8	import { collapseWhitespace, wrapText } from './textwrap.mjs';
9	
10	const INDENT_INCREMENT = 2;
11	const MAX_HELP_POSITION = 24;
12	
13	/**
14	 * `_format_usage`'s part splitter: bracketed/parenthesised groups stay whole,
15	 * everything else splits on whitespace.
16	 */
17	const PART_PATTERN = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;
18	
19	export class HelpFormatter {
20	  /**
21	   * @param {string} prog program name
22	   * @param {number} columns terminal width
23	   */
24	  constructor(prog, columns) {
25	    this.prog = prog;
26	    this.width = columns - 2;
27	    this.currentIndent = 0;
28	    this.maxHelpPosition = Math.min(
29	      MAX_HELP_POSITION,
30	      Math.max(this.width - 20, INDENT_INCREMENT * 2),
31	    );
32	  }
33	
34	  /**
35	   * How an action appears in the usage line: `[-h]`, `--key KEY`.
36	   *
37	   * @param {object} action
38	   * @returns {string}
39	   */
40	  usagePart(action) {
41	    const optionString = action.optionStrings[0];
42	    const part = action.nargs === 0 ? optionString : `${optionString} ${action.metavar}`;
43	    return action.required ? part : `[${part}]`;
44	  }
45	
46	  /**
47	   * How an action appears in the options list: `-h, --help`, `--key KEY`.
48	   *
49	   * @param {object} action
50	   * @returns {string}
51	   */
52	  invocation(action) {
53	    if (action.nargs === 0) return action.optionStrings.join(', ');
54	    return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
55	  }
56	
57	  /**
58	   * The width of the widest invocation plus its indent, i.e. argparse's
59	   * `_action_max_length`.
60	   *
61	   * @param {object[]} actions
62	   * @returns {number}
63	   */
64	  actionMaxLength(actions) {
65	    let longest = 0;
66	    for (const action of actions) {
67	      longest = Math.max(longest, this.invocation(action).length + INDENT_INCREMENT);
68	    }
69	    return longest;
70	  }
71	
72	  /**
73	   * Greedy line packing shared by both usage-wrapping branches, mirroring the
74	   * nested `get_lines` helper in `_format_usage`.
75	   *
76	   * @param {string[]} parts
77	   * @param {string} indent
78	   * @param {number} textWidth
79	   * @param {string | null} prefix
80	   * @returns {string[]}
81	   */
82	  static packLines(parts, indent, textWidth, prefix = null) {
83	    const lines = [];
84	    let line = [];
85	    let lineLength = (prefix === null ? indent.length : prefix.length) - 1;
86	
87	    for (const part of parts) {
88	      if (lineLength + 1 + part.length > textWidth && line.length > 0) {
89	        lines.push(indent + line.join(' '));
90	        line = [];
91	        lineLength = indent.length - 1;
92	      }
93	      line.push(part);
94	      lineLength += 1 + part.length;
95	    }
96	    if (line.length > 0) lines.push(indent + line.join(' '));
97	    if (prefix !== null && lines.length > 0) lines[0] = lines[0].slice(indent.length);
98	    return lines;
99	  }
100	
101	  /**
102	   * The `usage: ...` block, wrapped if it does not fit the terminal.
103	   *
104	   * @param {object[]} actions
105	   * @returns {string} ends with a single newline
106	   */
107	  formatUsage(actions) {
108	    const prefix = 'usage: ';
109	    const actionUsage = actions.map((action) => this.usagePart(action)).join(' ');
110	    let usage = [this.prog, actionUsage].filter((piece) => piece !== '').join(' ');
111	    const textWidth = this.width - this.currentIndent;
112	
113	    if (prefix.length + usage.length > textWidth) {
114	      const optionalParts = actionUsage.match(PART_PATTERN) ?? [];
115	      let lines;
116	      if (prefix.length + this.prog.length <= 0.75 * textWidth) {
117	        const indent = ' '.repeat(prefix.length + this.prog.length + 1);
118	        lines =
119	          optionalParts.length > 0
120	            ? HelpFormatter.packLines([this.prog, ...optionalParts], indent, textWidth, prefix)
121	            : [this.prog];
122	      } else {
123	        const indent = ' '.repeat(prefix.length);
124	        lines = HelpFormatter.packLines(optionalParts, indent, textWidth);
125	        lines = [this.prog, ...lines];
126	      }
127	      usage = lines.join('\n');
128	    }
129	
130	    return `${prefix}${usage}\n`;
131	  }
