import { readFileSync, writeFileSync } from 'node:fs';
const lines = readFileSync('/tmp/ap2.jsonl', 'utf8').split('\n').filter((l) => l.trim());
const bad = [];
const good = [];
for (const l of lines) {
  const c = JSON.parse(l);
  const hasNul = c.args.some((a) => typeof a === 'string' && a.includes('�'));
  (hasNul ? bad : good).push(l);
}
writeFileSync('/tmp/ap3.jsonl', good.join('\n') + '\n');
console.log('good', good.length, 'dropped', bad.length);
